mapper.select:
SELECT B.BranchId, B.BranchCode, B.BranchName, D.VatRate, SUM(D.SalePrice) AS SaleAmt, SUM(D.BuyPrice) AS BuyAmt, SUM(D.ProdMargin) AS ProdMargin
FROM shopwizard.tAdjAdjustDetail D
INNER JOIN shopion.tOrdOrder O ON O.OrderNo = D.OrderNo
INNER JOIN shopion.tPrfCust C ON C.CustId = O.CustId
INNER JOIN shopion.tPrfBranch B ON B.BranchId = C.BranchId
INNER JOIN shopion.tPrfComp Cm ON Cm.CompCode = C.CompCode

    AND CmpletDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d')
    AND CmpletDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY)
    AND SaleAdjustCloseDate IS NULL
    AND BuyAdjustCloseDate IS NULL
    AND ChnlCode = #{pChnlCode}
    AND ShopCode = #{pShopCode}
    AND EXISTS (SELECT * FROM shopwizard.tCmpChnl Ch WHERE D.ChnlCode = Ch.ChnlCode AND Ch.SvcCode = #{pSvcCode})
    AND C.CompCode = #{pCompCode}
    AND AdjustDetailNo = #{pAdjustDetailNo}
    AND AdjustNo = #{pAdjustNo}
    AND SaleAdjustNo = #{pSaleAdjustNo}

GROUP BY B.BranchId, B.BranchCode, B.BranchName, D.VatRate

SELECT S.ShopCode, S.ShopName, D.VatRate, SUM(D.SalePrice) AS SaleAmt, SUM(D.BuyPrice) AS BuyAmt, SUM(D.ProdMargin) AS ProdMargin, SUM(D.DeliFeeAmt) AS DeliFeeAmt
FROM shopwizard.tAdjAdjustDetail D
INNER JOIN shopwizard.tCmpShop S ON S.ShopCode = D.ShopCode

    AND D.CmpletDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d')
    AND D.CmpletDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY)
    AND D.SaleAdjustCloseDate IS NULL
    AND D.BuyAdjustCloseDate IS NULL
    AND D.ChnlCode = #{pChnlCode}
    AND D.ShopCode = #{pShopCode}
    AND S.SvcCode = #{pSvcCode}
    AND D.AdjustDetailNo = #{pAdjustDetailNo}
    AND D.AdjustNo = #{pAdjustNo}
    AND D.SaleAdjustNo = #{pSaleAdjustNo}
    AND S.adjustPeriodCode = #{pAdjustPeriodType}

GROUP BY S.ShopCode, S.ShopName, D.VatRate

mapper.insert:
INSERT INTO shopwizard.tAdjAdjustDetail (OrderNo, OrderProdNo, OrderChangeNo, CustName, SupplyCode, SupplyName, ShopCode, ShopName, BundleYn, CateCode, StoreCode, ProdCode, ShopProdCode, ItemCode, ProdName, ProdImg, ItemName, ProdQty, ListPrice, PrevPrice, SalePrice, SaleDiscntAmt, CustCpnDiscntAmt, ProdCpnDiscntAmt, PointUseAmt, SupplyPrice, DiscntSupplyPrice, BuyPrice, NvPrice, PvPrice, PointSaveAmt, VatRate, VatAmt, CustChrgDeliFee, DeliFeeId, DeliFeeType, DeliFeeAmt, DeliCompCode, PromotFeeAmt, PrevInvNo, InvNo, SaleConfrmDate, CmpletDate, OrderState, ChnlCode, State, Remark, RegistId, RegistName, RegistDate)
SELECT OrderNo, OrderProdNo, OrderChangeNo, OrderName, SupplyCode, SupplyName, ShopCode, ShopName, BundleYn, CateCode, StoreCode, ProdCode, ShopProdCode, ItemCode, ProdName, ProdImg, ItemName, ProdQty, ListPrice, PrevPrice, SalePrice, SaleDiscntAmt, CustCpnDiscntAmt, ProdCpnDiscntAmt, PointUseAmt, SupplyPrice, DiscntSupplyPrice, BuyPrice, NvPrice, PvPrice, PointSaveAmt, VatRate, VatAmt, CustChrgDeliFee, DeliFeeId, DeliFeeType, DeliFeeAmt, DeliCompCode, PromotFeeAmt, PrevInvNo, InvNo, ShipCmpletDate, ShipCmpletDate, OrderState, ChnlCode, State, Remark, #{changeId}, #{changeName}, NOW()
FROM shopwizard.tShpShipDirect WHERE (ShipCmpletDate IS NOT NULL AND ShipCmpletDate != '') AND OrderNo = #{orderNo} AND OrderProdNo = #{orderProdNo} AND OrderChangeNo = #{orderChangeNo}
UNION ALL
SELECT OrderNo, OrderProdNo, OrderChangeNo, OrderName, SupplyCode, SupplyName, ShopCode, ShopName, BundleYn, CateCode, StoreCode, ProdCode, ShopProdCode, ItemCode, ProdName, ProdImg, ItemName, -1*ProdQty, -1*ListPrice, -1*PrevPrice, -1*SalePrice, -1*SaleDiscntAmt, -1*CustCpnDiscntAmt, -1*ProdCpnDiscntAmt, -1*PointUseAmt, -1*SupplyPrice, -1*DiscntSupplyPrice, -1*BuyPrice, -1*NvPrice, -1*PvPrice, -1*PointSaveAmt, -1*VatRate, -1*VatAmt, -1*CustChrgDeliFee, DeliFeeId, DeliFeeType, -1*DeliFeeAmt, DeliCompCode, PromotFeeAmt, PrevInvNo, InvNo, ReturnCmpletDate, ReturnCmpletDate, OrderState, ChnlCode, State, Remark, #{changeId}, #{changeName}, NOW()
FROM shopwizard.tShpReturnDirect WHERE (ReturnCmpletDate IS NOT NULL AND ReturnCmpletDate != '') AND OrderNo = #{orderNo} AND OrderProdNo = #{orderProdNo} AND OrderChangeNo = #{orderChangeNo}

INSERT INTO shopwizard.tAdjAdjustDetail (OrderNo, OrderProdNo, OrderChangeNo, CustName, SupplyCode, SupplyName, ShopCode, ShopName, BundleYn, CateCode, StoreCode, ProdCode, ShopProdCode, ItemCode, ProdName, ProdImg, ItemName, ProdQty, ListPrice, PrevPrice, SalePrice, SaleDiscntAmt, CustCpnDiscntAmt, ProdCpnDiscntAmt, PointUseAmt, SupplyPrice, DiscntSupplyPrice, BuyPrice, NvPrice, PvPrice, PointSaveAmt, VatRate, VatAmt, CustChrgDeliFee, DeliFeeId, DeliFeeType, DeliFeeAmt, DeliCompCode, PromotFeeAmt, PrevInvNo, InvNo, SaleConfrmDate, CmpletDate, OrderState, ChnlCode, State, Remark, RegistId, RegistName, RegistDate)
SELECT OP.OrderNo, OP.OrderProdNo, 0 AS OrderChangeNo, O.OrderName, OP.SupplyCode, OP.SupplyName, OP.ShopCode, OP.ShopName, OP.BundleYn, '' AS CateCode, OP.StoreCode, OP.ProdCode, OP.ShopProdCode, OP.ItemCode, OP.ProdName, OP.ProdImg, OP.ItemName, OP.ProdQty, OP.ListPrice, OP.PrevPrice, OP.SalePrice, OP.SaleDiscntAmt, OP.CustCpnDiscntAmt, OP.ProdCpnDiscntAmt, OP.PointUseAmt, OP.SupplyPrice, 0, OP.BuyPrice, OP.NvPrice, OP.PvPrice, OP.PointSaveAmt, OP.VatRate, OP.VatAmt, OP.DeliFeeAmt, OP.DeliFeeId, OP.DeliFeeType, OP.DeliFeeAmt, OP.DeliCompCode, OP.PromotFeeAmt, OP.PrevInvNo, OP.InvNo, OP.ShipCmpletDate, OP.ShipCmpletDate, OP.OrderState, O.ChnlCode, 1, '', #{changeId}, #{changeName}, NOW() FROM shopion.tOrdOrderProd OP INNER JOIN shopion.tOrdOrder O ON O.OrderNo = OP.OrderNo WHERE OP.ShipCmpletDate IS NOT NULL AND OP.ShipCmpletDate != '' AND OP.OrderNo = #{orderNo} AND OP.OrderProdNo = #{orderProdNo}
SELECT OP.OrderNo, OP.OrderProdNo, 0 AS OrderChangeNo, O.OrderName, OP.SupplyCode, OP.SupplyName, OP.ShopCode, OP.ShopName, OP.BundleYn, '' AS CateCode, OP.StoreCode, OP.ProdCode, OP.ShopProdCode, OP.ItemCode, OP.ProdName, OP.ProdImg, OP.ItemName, -1*OP.ProdQty, -1*OP.ListPrice, -1*OP.PrevPrice, -1*OP.SalePrice, -1*OP.SaleDiscntAmt, -1*OP.CustCpnDiscntAmt, -1*OP.ProdCpnDiscntAmt, -1*OP.PointUseAmt, -1*OP.SupplyPrice, 0, -1*OP.BuyPrice, -1*OP.NvPrice, -1*OP.PvPrice, -1*OP.PointSaveAmt, OP.VatRate, -1*OP.VatAmt, -1*OP.DeliFeeAmt, OP.DeliFeeId, OP.DeliFeeType, -1*OP.DeliFeeAmt, OP.DeliCompCode, OP.PromotFeeAmt, OP.PrevInvNo, OP.InvNo, OP.ShipCmpletDate, OP.RefundCmpletDate, OP.OrderState, O.ChnlCode, 1, '', #{changeId}, #{changeName}, NOW() FROM shopion.tOrdOrderProd OP INNER JOIN shopion.tOrdOrder O ON O.OrderNo = OP.OrderNo WHERE OP.ShipCmpletDate IS NOT NULL AND OP.ShipCmpletDate != '' AND OP.RefundCmpletDate IS NOT NULL AND OP.RefundCmpletDate != '' AND OP.OrderNo = #{orderNo} AND OP.OrderProdNo = #{orderProdNo}
